from itertools import combinations
n=23;m=11
vectors={}
subs=[]
def diffvec(S):
    s=set(S)
    return tuple(sum(1 for a in s if (a+k)%n in s) for k in range(1,n))
count=0
for comb in combinations(range(1,n), m-1):
    S=(0,)+comb
    v=diffvec(S)
    if v not in vectors:
        vectors[v]=S
    count+=1
print('count', count, 'unique', len(vectors))
for v,S in list(vectors.items()):
    target=tuple(10-x for x in v)
    if target in vectors:
        print('found', S, vectors[target])
        print(v, target)
        raise SystemExit
print('not found')
